import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // root container
  const root = new Group();

  // geometry & material for the textured plane
  const geometry = new PlaneGeometry(2, 1.25);
  const material = new MeshBasicNodeMaterial({ map: null, transparent: true });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // async texture load (sync function)
  let texture;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    texture = tex;
    material.map = tex;
    material.needsUpdate = true;
  });

  // apply cinematic primitives from config
  const primInstances = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    const fn = ctx.primitives[p.name];
    if (fn) {
      const inst = fn(root, p.params || {});
      primInstances.push(inst);
    }
  }

  // GSAP timelines for interactions
  const hoverTL = gsap.timeline({ paused: true }).to(mesh.position, {
    y: '+=0.15',
    duration: 0.7,
    ease: 'power3.out',
  });

  const clickTL = gsap.timeline({ paused: true }).to(mesh.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out',
  });

  // event handlers attached to userData
  root.userData.handlers = {
    hover: () => {
      hoverTL.restart();
    },
    click: () => {
      clickTL.restart();
      ctx.emit('hub-pricing.select');
    },
  };

  // cleanup routine
  root.userData.cleanup = () => {
    // dispose three.js resources
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();

    // kill GSAP timelines
    hoverTL.kill();
    clickTL.kill();

    // cleanup primitives
    for (const inst of primInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
  };

  return root;
}
